تور-أو{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.93);display:none;align-items:center;justify-content:center;padding:20px}
      سورة البقرة.vis{display:flex}
      كيس تور{background:#0a0a0a;border:1.5px solid #12A5FF;border-radius:20px;padding:36px 28px 24px;max-width:420px;width:100%;font-family:inherit}
      tslide{display:none;min-height:160px}
      tslide.on{display:block}
      tslide-icon{font-size:30px;text-align:center;margin-bottom:14px}
      Tslide كيكير{font-size:9px;font-weight:900;letter-spacing:3px;color:#12A5FF;text-transform:uppercase;text-align:center;margin-bottom:12px}
      tslide-جسم{font-size:15px;line-height:1.8;color:rgba(255,255,255,.88);text-align:center}
      tslide-body ب{color:#ff0000}
      tslide-body إم{color:#12A5FF;font-style:normal;font-weight:700}
      tdogs{display:flex;gap:7px;justify-content:center;margin:22px 0 16px}
      tdot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,.2);cursor:pointer;transition:background .2s}
      tdot.on{background:#12A5FF}
      tnav{display:flex;align-items:center;gap:8px}
      t-سباحة{flex:1;background:none;border:none;color:rgba(255,255,255,.3);font-size:11px;letter-spacing:1px;cursor:pointer;font-family:inherit;text-align:left;padding:0}
      T-Prev{background:none;border:1px solid rgba(255,255,255,.2);color:rgba(255,255,255,.5);font-size:14px;padding:9px 14px;border-radius:8px;cursor:pointer;font-family:inherit}
      التالي{background:#12A5FF;border:none;color:#000;font-size:12px;font-weight:900;padding:10px 22px;border-radius:10px;cursor:pointer;font-family:inherit;letter-spacing:1px;white-space:nowrap}
      مساعدة BTN{position:fixed;bottom:24px;right:24px;z-index:998;width:52px;height:52px;border-radius:50%;background:#ff0000;border:2px solid rgba(255,255,255,.25);color:#fff;font-size:22px;font-weight:900;cursor:pointer;font-family:inherit;animation:phb 2s ease-in-out infinite;display:flex;align-items:center;justify-content:center}
      كلمات مفتاحية phb{0٪،100٪{box-shadow:0 0 0 0 rgba(255,0,0,.65),0 0 12px rgba(255,0,0,.3)}55%{box-shadow:0 0 0 18px rgba(255,0,0,0),0 0 22px rgba(255,0,0,.1)}المساعدة{position:fixed;inset:0;z-index:9998;background:rgba(0,0,0,.88);display:none;align-items:center;justify-content:center;padding:20px}
      المساعدة.vis{display:flex}
      كيس المساعد{background:#0a0a0a;border:1.5px solid #ff0000;border-radius:16px;padding:28px 22px;max-width:420px;width:100%;font-family:inherit;box-shadow:0 0 30px rgba(255,0,0,.12)}
      المساعدة Sec{font-size:9px;font-weight:900;letter-spacing:2.5px;color:#ff0000;text-transform:uppercase;margin-bottom:10px}
      مساعدة txt{font-size:14px;line-height:1.75;color:rgba(255,255,255,.9);margin:0 0 20px;white-space:pre-wrap}
      Hbts{display:flex;gap:8px}
      H-جولة{flex:1;background:rgba(18,165,255,.08);border:1px solid #12A5FF;color:#12A5FF;font-size:11px;font-weight:700;letter-spacing:1px;padding:10px;border-radius:8px;cursor:pointer;font-family:inherit}
      H - قريبة{flex:1;background:#ff0000;border:none;color:#fff;font-size:11px;font-weight:900;letter-spacing:1px;padding:10px;border-radius:8px;cursor:pointer;font-family:inherit}

