عرض الطوارئ Quick View{position:fixed;inset:0;z-index:9999;display:none;
      background:#000;color:#fff;overflow-y:auto;
      font-family:Inter,system-ui,sans-serif;}
    إكف-الرأس{position:sticky;top:0;z-index:2;
      background:rgba(0,0,0,0.92);backdrop-filter:blur(6px);
      padding:16px;display:flex;align-items:center;justify-content:space-between;
      border-bottom:1px solid rgba(255,255,255,0.08);}
    إكف-عنوان{font-size:12px;font-weight:900;letter-spacing:2.5px;
      color:#12A5FF;text-shadow:0 0 8px #12A5FF;text-transform:uppercase;}
    إكسو قريبة{background:transparent;border:1.5px solid rgba(255,255,255,0.35);
      color:#fff;border-radius:20px;padding:8px 16px;font-size:11px;
      font-weight:700;letter-spacing:1px;cursor:pointer;text-transform:uppercase;
      font-family:inherit;}
    أرشيف الوسم : Hover{background:rgba(255,255,255,0.08);}
    شبكة EQV{display:flex;flex-direction:column;align-items:center;
      gap:36px;padding:20px 20px 40px;max-width:480px;margin:0 auto;}
    بطاقة EQV{display:flex;flex-direction:column;align-items:center;gap:12px;width:100%;}
    أرشيف الأوسمة{display:flex;align-items:center;justify-content:center;
      gap:9px;width:100%;}
    أرشيف الوسم : DOT{width:13px;height:13px;border-radius:50%;flex-shrink:0;}
    أرشيف الأوسمة{font-size:16px;font-weight:900;letter-spacing:1.2px;
      text-transform:uppercase;text-align:center;line-height:1.25;}
    إكف-غلاف{position:relative;border-radius:30px;background:#0a1422;
      display:flex;align-items:center;justify-content:center;overflow:hidden;}
    إكف-غطاء إيمغ، . إكفي -غطاء قناة{width:90%;height:90%;object-fit:contain;
      border-radius:10px;background:#fff;display:block;}
    إيفو الاسم{font-size:13px;color:rgba(255,255,255,0.75);text-align:center;
      letter-spacing:0.3px;word-break:break-word;}
